/* ============================
   GREETING - 大きくて上品に
   ============================ */
.Greeting h2 {
  font-size: 5rem;
  font-weight: 200;
  letter-spacing: 0.08em;
  margin: 0;
  padding: 20px 0;
  background: linear-gradient(135deg, #ffffff 0%, rgba(255,255,255,0.6) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  filter: drop-shadow(0 4px 20px rgba(0,0,0,0.15));
  animation: fadeInUp 1.2s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(30px);
    filter: blur(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

/* ============================
   SEARCH BOX - フロステッドガラス
   ============================ */
.Search {
  position: relative;
  width: 520px;
  margin: 30px auto;
}

.Search input {
  width: 100%;
  box-sizing: border-box;
  padding: 18px 24px 18px 56px !important;
  font-size: 1.05rem !important;
  color: white !important;
  background: rgba(255,255,255,0.08) !important;
  border: 1px solid rgba(255,255,255,0.15) !important;
  border-radius: 100px !important;
  backdrop-filter: blur(24px) saturate(180%);
  -webkit-backdrop-filter: blur(24px) saturate(180%);
  box-shadow: 
    0 8px 32px rgba(0,0,0,0.12),
    inset 0 1px 0 rgba(255,255,255,0.15);
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  outline: none !important;
}

.Search input::placeholder {
  color: rgba(255,255,255,0.55);
  font-weight: 300;
  letter-spacing: 0.03em;
}

.Search input:focus {
  background: rgba(255,255,255,0.14) !important;
  border-color: rgba(255,255,255,0.35) !important;
  box-shadow: 
    0 12px 48px rgba(0,0,0,0.2),
    inset 0 1px 0 rgba(255,255,255,0.25),
    0 0 0 6px rgba(255,255,255,0.08);
  transform: translateY(-2px);
}

/* 虫眼鏡アイコンを疑似要素で追加 */
.Search::before {
  content: "";
  position: absolute;
  left: 22px;
  top: 50%;
  transform: translateY(-50%);
  width: 20px;
  height: 20px;
  background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><circle cx='11' cy='11' r='8'/><line x1='21' y1='21' x2='16.65' y2='16.65'/></svg>") no-repeat center/contain;
  opacity: 0.7;
  pointer-events: none;
  transition: opacity 0.3s;
}

.Search:focus-within::before {
  opacity: 1;
}

/* ============================
   LINKS - 右揃え
   ============================ */
.Links {
  text-align: left !important;
  justify-items: start !important;
}

.Links a {
  justify-content: flex-start;
}
